CREATE OR REPLACE FUNCTION public.add_order_items_v23(p_order uuid, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role text;
  v_order public.orders%ROWTYPE;
  v_line jsonb;
  v_menu public.menu_items%ROWTYPE;
  v_qty integer;
  v_new_total numeric := 0;
  v_adjustments numeric := 0;
  v_rec record;
  v_item public.inventory_items%ROWTYPE;
  v_bottles integer;
  v_events jsonb := '[]'::jsonb;
  v_lines jsonb := '[]'::jsonb;
BEGIN
  SELECT role INTO v_role FROM public.profiles
  WHERE id=auth.uid() AND active=true;
  IF v_role IS NULL OR v_role NOT IN ('admin','staff','cashier') THEN
    RAISE EXCEPTION 'Sin permiso para agregar productos';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id=p_order FOR UPDATE;
  IF NOT FOUND OR v_order.status <> 'open' THEN
    RAISE EXCEPTION 'La cuenta no está abierta';
  END IF;
  IF p_lines IS NULL OR jsonb_typeof(p_lines)<>'array'
     OR jsonb_array_length(p_lines) NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'Debes seleccionar entre 1 y 100 productos';
  END IF;

  -- Guardar nuevas líneas sin modificar las líneas ya confirmadas.
  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    IF jsonb_typeof(v_line->'id')<>'string'
       OR jsonb_typeof(v_line->'q')<>'number'
       OR (v_line->>'q') !~ '^[0-9]{1,3}$' THEN
      RAISE EXCEPTION 'Producto o cantidad inválida';
    END IF;
    v_qty := (v_line->>'q')::integer;
    IF v_qty NOT BETWEEN 1 AND 100 THEN
      RAISE EXCEPTION 'Cantidad permitida: 1 a 100';
    END IF;
    SELECT * INTO v_menu FROM public.menu_items
    WHERE id=(v_line->>'id')::uuid AND active=true AND manual_unavailable=false;
    IF NOT FOUND OR NOT EXISTS (
      SELECT 1 FROM public.menu_subcategories s
      JOIN public.menu_categories c ON c.id=s.category_id
      WHERE s.id=v_menu.subcategory_id AND s.active AND c.active
    ) THEN
      RAISE EXCEPTION 'Producto no disponible';
    END IF;

    INSERT INTO public.order_items
      (order_id,menu_item_id,item_name,unit_price,quantity,line_total,business)
    VALUES
      (p_order,v_menu.id,v_menu.name,v_menu.price,v_qty,v_menu.price*v_qty,v_menu.business);
    v_new_total := v_new_total + v_menu.price*v_qty;
    v_lines := v_lines || jsonb_build_object('id',v_menu.id,'qty',v_qty);
  END LOOP;

  -- Inventario solo de los nuevos productos, agrupado por insumo.
  FOR v_rec IN
    SELECT r.inventory_item_id, sum(r.quantity_required*(x->>'qty')::integer) AS qty
    FROM jsonb_array_elements(v_lines) x
    JOIN public.recipes r ON r.menu_item_id=(x->>'id')::uuid
    GROUP BY r.inventory_item_id ORDER BY r.inventory_item_id
  LOOP
    SELECT * INTO v_item FROM public.inventory_items
    WHERE id=v_rec.inventory_item_id FOR UPDATE;
    IF NOT FOUND OR NOT v_item.active OR v_item.manual_unavailable
       OR v_item.current_stock < v_rec.qty THEN
      RAISE EXCEPTION 'Inventario insuficiente: %',coalesce(v_item.name,'insumo');
    END IF;
    IF v_item.display_unit='botella' AND v_rec.qty>coalesce(v_item.open_bottle_ml,0) THEN
      IF coalesce(v_item.quantity_per_display_unit,0)<=0 THEN
        RAISE EXCEPTION 'Botella sin contenido válido';
      END IF;
      v_bottles := ceil((v_rec.qty-coalesce(v_item.open_bottle_ml,0))/v_item.quantity_per_display_unit)::integer;
      INSERT INTO public.bottle_open_events
        (inventory_item_id,order_id,bottle_ml,automatic,opened_by)
      SELECT v_item.id,p_order,v_item.quantity_per_display_unit,true,auth.uid()
      FROM generate_series(1,v_bottles);
      v_events := v_events || jsonb_build_object('name',v_item.name,'count',v_bottles);
    END IF;
    UPDATE public.inventory_items
    SET current_stock=current_stock-v_rec.qty,updated_at=now()
    WHERE id=v_item.id;
    INSERT INTO public.inventory_movements
      (inventory_item_id,movement_type,reason,quantity,direction,order_id,created_by)
    VALUES (v_item.id,'venta','Consumo adicional en cuenta abierta',
            v_rec.qty,'salida',p_order,auth.uid());
  END LOOP;

  -- Respeta cortesías y descuentos ya autorizados.
  SELECT coalesce(sum(amount),0) INTO v_adjustments
  FROM public.order_adjustments WHERE order_id=p_order;
  UPDATE public.orders
  SET total=greatest(0,
    (SELECT coalesce(sum(unit_price*quantity),0)
     FROM public.order_items WHERE order_id=p_order)-v_adjustments),
    updated_by=auth.uid(),updated_at=now()
  WHERE id=p_order RETURNING * INTO v_order;

  RETURN jsonb_build_object('order_id',p_order,'total',v_order.total,
                            'added_amount',v_new_total,'opened_bottles',v_events);
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_order_adjustment_v2(p_order uuid, p_kind text, p_reason text, p_percent numeric DEFAULT NULL::numeric, p_order_item uuid DEFAULT NULL::uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_order public.orders%rowtype;v_base numeric;v_amount numeric;
BEGIN
 IF NOT public.is_admin() THEN RAISE EXCEPTION 'Solo administrador'; END IF;
 IF nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Motivo obligatorio'; END IF;
 SELECT * INTO v_order FROM public.orders WHERE id=p_order FOR UPDATE;
 IF NOT FOUND OR v_order.status<>'open' THEN RAISE EXCEPTION 'Solo cuentas abiertas'; END IF;
 IF EXISTS(SELECT 1 FROM public.order_adjustments WHERE order_id=p_order) THEN RAISE EXCEPTION 'La cuenta ya tiene una autorización; no se permiten ajustes acumulados'; END IF;
 IF p_order_item IS NULL THEN
   SELECT coalesce(sum(unit_price*quantity),0) INTO v_base FROM public.order_items WHERE order_id=p_order;
 ELSE
   SELECT unit_price*quantity INTO v_base FROM public.order_items WHERE id=p_order_item AND order_id=p_order;
   IF NOT FOUND THEN RAISE EXCEPTION 'Artículo no pertenece a esta cuenta'; END IF;
 END IF;
 IF v_base<=0 THEN RAISE EXCEPTION 'Importe inválido'; END IF;
 IF p_kind='discount' THEN
   IF p_percent IS NULL OR p_percent<1 OR p_percent>30 THEN RAISE EXCEPTION 'Descuento permitido: 1 a 30 por ciento'; END IF;
   v_amount:=round(v_base*p_percent/100,2);
 ELSIF p_kind='complimentary' THEN
   IF p_percent IS NOT NULL THEN RAISE EXCEPTION 'La cortesía no lleva porcentaje'; END IF;
   v_amount:=round(v_base,2);
 ELSE RAISE EXCEPTION 'Tipo inválido'; END IF;
 INSERT INTO public.order_adjustments(order_id,order_item_id,kind,percent,reason,amount,authorized_by)
 VALUES(p_order,p_order_item,p_kind,p_percent,trim(p_reason),v_amount,auth.uid());
 UPDATE public.orders SET total=greatest(0,(SELECT coalesce(sum(unit_price*quantity),0) FROM public.order_items WHERE order_id=p_order)-v_amount),updated_by=auth.uid(),updated_at=now() WHERE id=p_order;
 RETURN v_amount;
END $function$

CREATE OR REPLACE FUNCTION public.audit_sales_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE' then
    insert into public.audit_log(table_name,record_id,action,changed_by,old_data,new_data)
    values ('sales',new.id,'UPDATE',auth.uid(),to_jsonb(old),to_jsonb(new));
    new.updated_at = now();
    new.updated_by = auth.uid();
    return new;
  elsif tg_op = 'DELETE' then
    insert into public.audit_log(table_name,record_id,action,changed_by,old_data,new_data)
    values ('sales',old.id,'DELETE',auth.uid(),to_jsonb(old),null);
    return old;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.bottle_outflow_track()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare x public.inventory_items%rowtype; v numeric; extra numeric; n integer;
begin
 if new.direction <> 'salida' then return new; end if;
 select * into x from public.inventory_items where id=new.inventory_item_id for update;
 if not found or x.display_unit <> 'botella' then return new; end if;
 v:=x.open_bottle_ml-new.quantity;
 n:=x.open_bottle_count;
 while v<0 and x.quantity_per_display_unit>0 loop
   v:=v+x.quantity_per_display_unit;
   n:=n+1;
 end loop;
 if v=0 then n:=0;
 elsif v>0 then n:=greatest(1,ceil(v/x.quantity_per_display_unit)::integer); end if;
 update public.inventory_items set open_bottle_ml=greatest(v,0),open_bottle_count=n where id=x.id;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.cancel_order_item_v26(p_order uuid, p_order_item uuid, p_quantity integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_order public.orders%ROWTYPE; v_item public.order_items%ROWTYPE; v_total numeric;
BEGIN
 IF NOT public.is_admin() THEN RAISE EXCEPTION 'Solo administrador puede cancelar productos'; END IF;
 IF p_quantity IS NULL OR p_quantity<1 THEN RAISE EXCEPTION 'Cantidad inválida'; END IF;
 IF nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Motivo obligatorio'; END IF;
 SELECT * INTO v_order FROM public.orders WHERE id=p_order FOR UPDATE;
 IF NOT FOUND OR v_order.status <> 'open' THEN RAISE EXCEPTION 'Solo se cancelan productos de cuentas abiertas'; END IF;
 -- Evitar recalcular mal descuentos/cortesías monetarias existentes.
 IF EXISTS(SELECT 1 FROM public.order_adjustments WHERE order_id=p_order) THEN
  RAISE EXCEPTION 'Esta cuenta ya tiene un descuento o cortesía monetaria; no es posible cancelar artículos sin revisar el ajuste'; END IF;
 SELECT * INTO v_item FROM public.order_items WHERE id=p_order_item AND order_id=p_order FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Producto no encontrado en la cuenta'; END IF;
 IF p_quantity>v_item.quantity THEN RAISE EXCEPTION 'Cantidad mayor que la registrada'; END IF;
 INSERT INTO public.order_cancellations_v26(order_id,order_item_id,item_name,quantity,unit_price,amount,reason,authorized_by)
 VALUES(p_order,p_order_item,v_item.item_name,p_quantity,v_item.unit_price,p_quantity*v_item.unit_price,trim(p_reason),auth.uid());
 IF p_quantity=v_item.quantity THEN
  DELETE FROM public.order_items WHERE id=p_order_item;
 ELSE
  UPDATE public.order_items SET quantity=quantity-p_quantity,line_total=unit_price*(quantity-p_quantity) WHERE id=p_order_item;
 END IF;
 SELECT coalesce(sum(unit_price*quantity),0) INTO v_total FROM public.order_items WHERE order_id=p_order;
 UPDATE public.orders SET total=v_total,updated_by=auth.uid(),updated_at=now() WHERE id=p_order;
 -- IMPORTANTE: no se inserta ningún movimiento de inventario ni se devuelve stock.
 RETURN jsonb_build_object('total',v_total,'cancelled',p_quantity,'item_name',v_item.item_name);
END $function$

CREATE OR REPLACE FUNCTION public.cancel_order_item_v27(p_order uuid, p_order_item uuid, p_quantity integer, p_reason text, p_return_stock boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
 v_order public.orders%ROWTYPE;
 v_line public.order_items%ROWTYPE;
 v_recipe record;
 v_stock public.inventory_items%ROWTYPE;
 v_total numeric;
BEGIN
 IF NOT public.is_admin() THEN RAISE EXCEPTION 'Solo administrador puede cancelar productos'; END IF;
 IF p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Cantidad inválida'; END IF;
 IF nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Motivo obligatorio'; END IF;
 SELECT * INTO v_order FROM public.orders WHERE id=p_order FOR UPDATE;
 IF NOT FOUND OR v_order.status<>'open' THEN RAISE EXCEPTION 'Solo cuentas abiertas'; END IF;
 IF EXISTS(SELECT 1 FROM public.order_adjustments WHERE order_id=p_order) THEN
  RAISE EXCEPTION 'La cuenta tiene un ajuste monetario. Se requiere revisar el descuento antes de cancelar';
 END IF;
 SELECT * INTO v_line FROM public.order_items WHERE id=p_order_item AND order_id=p_order FOR UPDATE;
 IF NOT FOUND OR p_quantity>v_line.quantity THEN RAISE EXCEPTION 'Cantidad o producto inválido'; END IF;
 IF p_return_stock AND v_line.menu_item_id IS NULL THEN RAISE EXCEPTION 'No se puede reponer: falta vínculo con el menú'; END IF;
 IF p_return_stock AND v_order.inventory_processed IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'No hay descuento de inventario confirmado para esta cuenta';
 END IF;

 IF p_return_stock THEN
  FOR v_recipe IN
   SELECT inventory_item_id,sum(quantity_required*p_quantity) qty
   FROM public.recipes WHERE menu_item_id=v_line.menu_item_id
   GROUP BY inventory_item_id ORDER BY inventory_item_id
  LOOP
   SELECT * INTO v_stock FROM public.inventory_items WHERE id=v_recipe.inventory_item_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Insumo de receta no encontrado'; END IF;
   UPDATE public.inventory_items SET current_stock=current_stock+v_recipe.qty,updated_at=now()
   WHERE id=v_stock.id;
   INSERT INTO public.inventory_movements
    (inventory_item_id,movement_type,reason,quantity,direction,order_id,created_by,business)
   VALUES(v_stock.id,'ajuste','Reposición por cancelación: '||trim(p_reason),
    v_recipe.qty,'entrada',p_order,auth.uid(),v_line.business);
  END LOOP;
 END IF;

 INSERT INTO public.order_cancellations_v26
  (order_id,order_item_id,item_name,quantity,unit_price,amount,reason,authorized_by,returned_to_inventory)
 VALUES(p_order,p_order_item,v_line.item_name,p_quantity,v_line.unit_price,
  p_quantity*v_line.unit_price,trim(p_reason),auth.uid(),coalesce(p_return_stock,false));
 IF p_quantity=v_line.quantity THEN
  DELETE FROM public.order_items WHERE id=p_order_item;
 ELSE
  UPDATE public.order_items SET quantity=quantity-p_quantity,line_total=unit_price*(quantity-p_quantity)
  WHERE id=p_order_item;
 END IF;
 SELECT coalesce(sum(unit_price*quantity),0) INTO v_total FROM public.order_items WHERE order_id=p_order;
 UPDATE public.orders SET total=v_total,updated_by=auth.uid(),updated_at=now() WHERE id=p_order;
 RETURN jsonb_build_object('total',v_total,'cancelled',p_quantity,
   'item_name',v_line.item_name,'returned_to_inventory',coalesce(p_return_stock,false));
END $function$

CREATE OR REPLACE FUNCTION public.cancel_order_item_v29(p_order uuid, p_order_item uuid, p_quantity integer, p_reason text, p_return_stock boolean, p_discount_scope text DEFAULT NULL::text, p_discount_item uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
 v_order public.orders%ROWTYPE;
 v_line public.order_items%ROWTYPE;
 v_adj public.order_adjustments%ROWTYPE;
 v_recipe record;
 v_stock public.inventory_items%ROWTYPE;
 v_gross numeric;
 v_base numeric;
 v_amount numeric := 0;
 v_before numeric := 0;
 v_total numeric;
 v_scope text;
 v_target uuid;
 v_n integer;
BEGIN
 IF NOT public.is_admin() THEN RAISE EXCEPTION 'Solo administrador puede cancelar productos'; END IF;
 IF p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Cantidad inv谩lida'; END IF;
 IF nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Motivo obligatorio'; END IF;
 SELECT * INTO v_order FROM public.orders WHERE id=p_order FOR UPDATE;
 IF NOT FOUND OR v_order.status<>'open' THEN RAISE EXCEPTION 'Solo cuentas abiertas'; END IF;
 SELECT * INTO v_line FROM public.order_items WHERE id=p_order_item AND order_id=p_order FOR UPDATE;
 IF NOT FOUND OR p_quantity>v_line.quantity THEN RAISE EXCEPTION 'Cantidad o producto inv谩lido'; END IF;
 SELECT count(*) INTO v_n FROM public.order_adjustments WHERE order_id=p_order;
 IF v_n>1 THEN RAISE EXCEPTION 'La cuenta tiene varios ajustes; requiere revisi贸n manual'; END IF;
 IF v_n=1 THEN
  SELECT * INTO v_adj FROM public.order_adjustments WHERE order_id=p_order FOR UPDATE;
  v_before:=v_adj.amount;
  IF p_discount_scope NOT IN ('completa','parcial') THEN
   RAISE EXCEPTION 'Elige si el descuento contin煤a en cuenta completa o parcial';
  END IF;
  v_scope:=p_discount_scope;
  IF v_scope='parcial' THEN
   IF p_discount_item IS NULL THEN RAISE EXCEPTION 'Selecciona el producto que conservar谩 el descuento'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.order_items WHERE id=p_discount_item AND order_id=p_order
       AND (id<>p_order_item OR quantity>p_quantity)) THEN
    RAISE EXCEPTION 'El producto seleccionado ya no quedar谩 en la cuenta';
   END IF;
   v_target:=p_discount_item;
  ELSE
   v_target:=NULL;
  END IF;
 ELSE
  IF p_discount_scope IS NOT NULL OR p_discount_item IS NOT NULL THEN
   RAISE EXCEPTION 'La cuenta no tiene descuento monetario';
  END IF;
 END IF;
 IF p_return_stock AND v_line.menu_item_id IS NULL THEN
  RAISE EXCEPTION 'No se puede reponer: falta v铆nculo con el men煤'; END IF;
 IF p_return_stock AND v_order.inventory_processed IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'No hay descuento de inventario confirmado para esta cuenta'; END IF;

 -- Devoluci贸n s贸lo si el administrador confirm贸 que el producto es apto.
 IF p_return_stock THEN
  FOR v_recipe IN
   SELECT inventory_item_id,sum(quantity_required*p_quantity) qty
   FROM public.recipes WHERE menu_item_id=v_line.menu_item_id
   GROUP BY inventory_item_id ORDER BY inventory_item_id
  LOOP
   SELECT * INTO v_stock FROM public.inventory_items WHERE id=v_recipe.inventory_item_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Insumo de receta no encontrado'; END IF;
   UPDATE public.inventory_items SET current_stock=current_stock+v_recipe.qty,updated_at=now()
   WHERE id=v_stock.id;
   INSERT INTO public.inventory_movements
    (inventory_item_id,movement_type,reason,quantity,direction,order_id,created_by,business)
   VALUES(v_stock.id,'ajuste','Reposici贸n por cancelaci贸n: '||trim(p_reason),
    v_recipe.qty,'entrada',p_order,auth.uid(),v_line.business);
  END LOOP;
 END IF;

 -- Actualizar l铆neas antes de recalcular descuento.
 IF p_quantity=v_line.quantity THEN
  -- El descuento debe conservar su historial, pero no referenciar una l铆nea borrada.
  UPDATE public.order_adjustments SET order_item_id=NULL
  WHERE order_id=p_order AND order_item_id=p_order_item;
  DELETE FROM public.order_items WHERE id=p_order_item;
 ELSE
  UPDATE public.order_items SET quantity=quantity-p_quantity,
   line_total=unit_price*(quantity-p_quantity) WHERE id=p_order_item;
 END IF;
 SELECT coalesce(sum(unit_price*quantity),0) INTO v_gross FROM public.order_items WHERE order_id=p_order;
 IF v_n=1 THEN
  IF v_scope='completa' THEN
   v_base:=v_gross;
  ELSE
   SELECT unit_price*quantity INTO v_base FROM public.order_items
   WHERE id=v_target AND order_id=p_order;
   IF NOT FOUND THEN RAISE EXCEPTION 'Producto de descuento parcial no disponible'; END IF;
  END IF;
  IF v_adj.kind='discount' THEN
   IF v_adj.percent IS NULL OR v_adj.percent<1 OR v_adj.percent>30 THEN
    RAISE EXCEPTION 'Porcentaje de descuento inv谩lido'; END IF;
   v_amount:=round(v_base*v_adj.percent/100,2);
  ELSIF v_adj.kind='complimentary' THEN
   v_amount:=round(v_base,2);
  ELSE
   RAISE EXCEPTION 'Ajuste monetario desconocido';
  END IF;
  UPDATE public.order_adjustments SET amount=v_amount,order_item_id=v_target WHERE id=v_adj.id;
 END IF;
 v_total:=greatest(0,v_gross-v_amount);
 INSERT INTO public.order_cancellations_v26
  (order_id,order_item_id,item_name,quantity,unit_price,amount,reason,authorized_by,
   returned_to_inventory,business,disposition,discount_scope,discount_item_id,
   discount_amount_before,discount_amount_after)
 VALUES(p_order,p_order_item,v_line.item_name,p_quantity,v_line.unit_price,
  p_quantity*v_line.unit_price,trim(p_reason),auth.uid(),coalesce(p_return_stock,false),
  v_line.business,CASE WHEN p_return_stock THEN 'inventario' ELSE 'merma' END,
  v_scope,v_target,CASE WHEN v_n=1 THEN v_before ELSE NULL END,
  CASE WHEN v_n=1 THEN v_amount ELSE NULL END);
 UPDATE public.orders SET total=v_total,updated_by=auth.uid(),updated_at=now() WHERE id=p_order;
 RETURN jsonb_build_object('total',v_total,'cancelled',p_quantity,'item_name',v_line.item_name,
  'returned_to_inventory',coalesce(p_return_stock,false),'discount_amount',v_amount,
  'discount_scope',v_scope);
END $function$

CREATE OR REPLACE FUNCTION public.cash_close_v31(p_session uuid, p_counted numeric, p_next numeric, p_notes text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.cash_sessions_v31%rowtype; v_cash numeric; v_card numeric; v_transfer numeric; v_other numeric; v_entries numeric; v_out numeric; v_expected numeric; v_open integer;
begin
 if not public.is_admin() then raise exception 'Solo administración'; end if;
 select * into s from public.cash_sessions_v31 where id=p_session for update;
 if not found or s.status<>'open' then raise exception 'La caja no está abierta'; end if;
 if p_counted is null or p_counted<0 or p_next is null or p_next<0 or p_next>p_counted then raise exception 'Importes de cierre inválidos'; end if;
 select count(*) into v_open from public.orders where business_date=s.business_date and status='open';
 if v_open>0 then raise exception 'Hay cuentas abiertas. Ciérralas antes de cerrar caja'; end if;
 select coalesce(sum(total) filter(where lower(coalesce(payment_method,''))='efectivo'),0),
 coalesce(sum(total) filter(where lower(coalesce(payment_method,''))='tarjeta'),0),
 coalesce(sum(total) filter(where lower(coalesce(payment_method,''))='transferencia'),0),
 coalesce(sum(total) filter(where lower(coalesce(payment_method,'')) not in ('efectivo','tarjeta','transferencia')),0)
 into v_cash,v_card,v_transfer,v_other from public.orders where business_date=s.business_date and status='closed';
 if v_other<>0 then raise exception 'Hay cobros con método no identificado. Corrígelos antes de cerrar caja'; end if;
 select coalesce(sum(amount) filter(where kind='entry'),0),coalesce(sum(amount) filter(where kind in ('expense','withdrawal')),0) into v_entries,v_out from public.cash_movements_v31 where session_id=p_session;
 v_expected:=s.opening_fund+v_cash+v_entries-v_out;
 update public.cash_sessions_v31 set status='closed',closed_at=now(),closed_by=auth.uid(),counted_cash=p_counted,expected_cash=v_expected,difference=p_counted-v_expected,next_fund=p_next,notes=coalesce(p_notes,''),sales_cash=v_cash,sales_card=v_card,sales_transfer=v_transfer,sales_other=v_other where id=p_session;
end $function$

