CREATE OR REPLACE FUNCTION public.convert_inventory_quantity(p_quantity numeric, p_from text, p_to text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare f text:=lower(trim(coalesce(p_from,''))); t text:=lower(trim(coalesce(p_to,'')));
begin
  if p_quantity is null then return null; end if;
  if f=t then return p_quantity; end if;
  if f in ('kg','kilogramo','kilogramos') and t in ('g','gramo','gramos') then return p_quantity*1000; end if;
  if f in ('g','gramo','gramos') and t in ('kg','kilogramo','kilogramos') then return p_quantity/1000; end if;
  if f in ('l','lt','litro','litros') and t in ('ml','mililitro','mililitros') then return p_quantity*1000; end if;
  if f in ('ml','mililitro','mililitros') and t in ('l','lt','litro','litros') then return p_quantity/1000; end if;
  if f in ('pieza','piezas','unidad','unidades','botella','botellas','lata','latas') and t in ('pieza','piezas','unidad','unidades','botella','botellas','lata','latas') then return p_quantity; end if;
  raise exception 'No se puede convertir % a %',p_from,p_to;
end $function$

CREATE OR REPLACE FUNCTION public.create_order_v2(p_type text, p_table text, p_platform text, p_notes text, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
 v_order uuid; v_line jsonb; v_menu public.menu_items%rowtype; v_qty integer;
 v_total numeric:=0; v_rec record; v_item public.inventory_items%rowtype;
 v_count integer; v_events jsonb:='[]'::jsonb; v_role text;
BEGIN
 SELECT role INTO v_role FROM public.profiles WHERE id=auth.uid() AND active=true;
 IF v_role IS NULL OR v_role NOT IN ('admin','staff','cashier') THEN RAISE EXCEPTION 'Sin permiso'; END IF;
 IF p_type NOT IN ('table','takeaway','delivery') THEN RAISE EXCEPTION 'Tipo de pedido inválido'; END IF;
 IF p_type='table' AND (coalesce(p_table,'') !~ '^[0-9]{1,5}$' OR p_table::integer<1) THEN RAISE EXCEPTION 'Mesa inválida'; END IF;
 IF p_lines IS NULL OR jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Pedido vacío o demasiado grande'; END IF;
 INSERT INTO public.orders(table_number,order_type,delivery_platform,notes,status,total,created_by,assigned_to,inventory_processed)
 VALUES(CASE WHEN p_type='table' THEN p_table WHEN p_type='takeaway' THEN 'Para llevar' ELSE 'Delivery' END,p_type,CASE WHEN p_type='delivery' THEN p_platform ELSE NULL END,nullif(trim(p_notes),''),'open',0,auth.uid(),auth.uid(),false)
 RETURNING id INTO v_order;
 FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
   IF jsonb_typeof(v_line->'id')<>'string' OR jsonb_typeof(v_line->'q')<>'number' OR (v_line->>'q') !~ '^[0-9]{1,3}$' THEN RAISE EXCEPTION 'Línea inválida'; END IF;
   v_qty:=(v_line->>'q')::integer;
   IF v_qty<1 OR v_qty>100 THEN RAISE EXCEPTION 'Cantidad inválida'; END IF;
   SELECT * INTO v_menu FROM public.menu_items WHERE id=(v_line->>'id')::uuid AND active=true AND manual_unavailable=false;
   IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.menu_subcategories s JOIN public.menu_categories c ON c.id=s.category_id WHERE s.id=v_menu.subcategory_id AND s.active AND c.active) THEN RAISE EXCEPTION 'Producto no disponible'; END IF;
   INSERT INTO public.order_items(order_id,menu_item_id,item_name,unit_price,quantity,line_total,business)
   VALUES(v_order,v_menu.id,v_menu.name,v_menu.price,v_qty,v_menu.price*v_qty,v_menu.business);
   v_total:=v_total+v_menu.price*v_qty;
 END LOOP;
 -- Agrupar consumo de todas las recetas; bloqueo estable por id para evitar carreras.
 FOR v_rec IN SELECT r.inventory_item_id, sum(r.quantity_required*oi.quantity) AS qty
 FROM public.order_items oi JOIN public.recipes r ON r.menu_item_id=oi.menu_item_id
 WHERE oi.order_id=v_order GROUP BY r.inventory_item_id ORDER BY r.inventory_item_id LOOP
   SELECT * INTO v_item FROM public.inventory_items WHERE id=v_rec.inventory_item_id FOR UPDATE;
   IF NOT FOUND OR NOT v_item.active OR v_item.manual_unavailable OR v_item.current_stock<v_rec.qty THEN
     RAISE EXCEPTION 'Inventario insuficiente o no disponible: %',coalesce(v_item.name,'insumo');
   END IF;
   IF v_item.display_unit='botella' AND v_rec.qty>v_item.open_bottle_ml THEN
     IF v_item.quantity_per_display_unit<=0 THEN RAISE EXCEPTION 'Botella sin contenido válido'; END IF;
     v_count:=ceil((v_rec.qty-v_item.open_bottle_ml)/v_item.quantity_per_display_unit)::integer;
     INSERT INTO public.bottle_open_events(inventory_item_id,order_id,bottle_ml,automatic,opened_by)
     SELECT v_item.id,v_order,v_item.quantity_per_display_unit,true,auth.uid() FROM generate_series(1,v_count);
     v_events:=v_events||jsonb_build_object('name',v_item.name,'count',v_count,'ml',v_item.quantity_per_display_unit);
   END IF;
   UPDATE public.inventory_items SET current_stock=current_stock-v_rec.qty,updated_at=now() WHERE id=v_item.id;
   -- Disparador existente actualiza open_bottle_ml y open_bottle_count.
   INSERT INTO public.inventory_movements(inventory_item_id,movement_type,reason,quantity,direction,order_id,created_by)
   VALUES(v_item.id,'venta','Pedido confirmado',v_rec.qty,'salida',v_order,auth.uid());
 END LOOP;
 UPDATE public.orders SET total=v_total,inventory_processed=true WHERE id=v_order;
 RETURN jsonb_build_object('order_id',v_order,'opened_bottles',v_events);
END $function$

CREATE OR REPLACE FUNCTION public.inventory_yield(p_inventory_item uuid, p_serving_quantity numeric, p_serving_unit text)
 RETURNS TABLE(stock_quantity numeric, stock_unit text, servings integer, remainder numeric)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare s numeric; u text; req numeric;
begin
 select current_stock, coalesce(display_unit,unit,base_unit,'pieza') into s,u
 from public.inventory_items where id=p_inventory_item;
 if not found then raise exception 'Insumo no encontrado'; end if;
 req:=public.convert_inventory_quantity(p_serving_quantity,p_serving_unit,u);
 if req<=0 then raise exception 'La porción debe ser mayor a cero'; end if;
 stock_quantity:=s; stock_unit:=u; servings:=floor(s/req); remainder:=s-(servings*req);
 return next;
end $function$

CREATE OR REPLACE FUNCTION public.issue_account_courtesy_v26(p_order uuid, p_menu_item uuid, p_quantity integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_order public.orders%ROWTYPE; v_menu public.menu_items%ROWTYPE; v_rec record;
 v_item public.inventory_items%ROWTYPE; v_count integer; v_id uuid;
BEGIN
 IF NOT public.is_admin() THEN RAISE EXCEPTION 'Solo administrador'; END IF;
 IF p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Cantidad inválida'; END IF;
 IF nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Motivo obligatorio'; END IF;
 SELECT * INTO v_order FROM public.orders WHERE id=p_order FOR UPDATE;
 IF NOT FOUND OR v_order.status <> 'open' THEN RAISE EXCEPTION 'La cuenta no está abierta'; END IF;
 SELECT * INTO v_menu FROM public.menu_items WHERE id=p_menu_item AND active AND NOT manual_unavailable;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.menu_subcategories s JOIN public.menu_categories c ON c.id=s.category_id
 WHERE s.id=v_menu.subcategory_id AND s.active AND c.active) THEN RAISE EXCEPTION 'Producto no disponible'; END IF;
 FOR v_rec IN SELECT inventory_item_id,sum(quantity_required*p_quantity) qty FROM public.recipes
 WHERE menu_item_id=p_menu_item GROUP BY inventory_item_id ORDER BY inventory_item_id LOOP
  SELECT * INTO v_item FROM public.inventory_items WHERE id=v_rec.inventory_item_id FOR UPDATE;
  IF NOT FOUND OR NOT v_item.active OR v_item.manual_unavailable OR v_item.current_stock<v_rec.qty THEN
   RAISE EXCEPTION 'Inventario insuficiente: %',coalesce(v_item.name,'insumo'); END IF;
  IF v_item.display_unit='botella' AND v_rec.qty>coalesce(v_item.open_bottle_ml,0) THEN
   IF coalesce(v_item.quantity_per_display_unit,0)<=0 THEN RAISE EXCEPTION 'Botella sin contenido válido'; END IF;
   v_count:=ceil((v_rec.qty-coalesce(v_item.open_bottle_ml,0))/v_item.quantity_per_display_unit)::integer;
   INSERT INTO public.bottle_open_events(inventory_item_id,order_id,bottle_ml,automatic,opened_by)
   SELECT v_item.id,p_order,v_item.quantity_per_display_unit,true,auth.uid() FROM generate_series(1,v_count);
  END IF;
  UPDATE public.inventory_items SET current_stock=current_stock-v_rec.qty,updated_at=now() WHERE id=v_item.id;
  INSERT INTO public.inventory_movements(inventory_item_id,movement_type,reason,quantity,direction,order_id,created_by,business)
  VALUES(v_item.id,'cortesia','Cortesía de cuenta: '||trim(p_reason),v_rec.qty,'salida',p_order,auth.uid(),v_menu.business);
 END LOOP;
 INSERT INTO public.account_courtesies_v26(order_id,menu_item_id,item_name,business,quantity,unit_price,reason,authorized_by)
 VALUES(p_order,v_menu.id,v_menu.name,v_menu.business,p_quantity,v_menu.price,trim(p_reason),auth.uid()) RETURNING id INTO v_id;
 RETURN jsonb_build_object('id',v_id,'item_name',v_menu.name,'quantity',p_quantity,'order_id',p_order);
END $function$

CREATE OR REPLACE FUNCTION public.issue_free_courtesy_v25(p_menu_item uuid, p_quantity integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
 v_menu public.menu_items%ROWTYPE;
 v_rec record;
 v_item public.inventory_items%ROWTYPE;
 v_count integer;
 v_id uuid;
BEGIN
 IF NOT public.is_admin() THEN RAISE EXCEPTION 'Solo administrador puede autorizar cortesías'; END IF;
