 IF NOT FOUND OR NOT EXISTS(
  SELECT 1 FROM public.menu_subcategories s
  JOIN public.menu_categories c ON c.id=s.category_id
  WHERE s.id=v_menu.subcategory_id AND s.active AND c.active
 ) THEN RAISE EXCEPTION 'Producto no disponible'; END IF;

 -- Descontar únicamente los ingredientes del producto seleccionado.
 FOR v_rec IN
  SELECT inventory_item_id, sum(quantity_required*p_quantity) qty
  FROM public.recipes WHERE menu_item_id=p_menu_item
  GROUP BY inventory_item_id ORDER BY inventory_item_id
 LOOP
  SELECT * INTO v_item FROM public.inventory_items WHERE id=v_rec.inventory_item_id FOR UPDATE;
  IF NOT FOUND OR NOT v_item.active OR v_item.manual_unavailable OR v_item.current_stock<v_rec.qty
  THEN RAISE EXCEPTION 'Inventario insuficiente: %',coalesce(v_item.name,'insumo'); END IF;
  IF v_item.display_unit='botella' AND v_rec.qty>coalesce(v_item.open_bottle_ml,0) THEN
   IF coalesce(v_item.quantity_per_display_unit,0)<=0 THEN RAISE EXCEPTION 'Botella sin contenido válido'; END IF;
   v_count:=ceil((v_rec.qty-coalesce(v_item.open_bottle_ml,0))/v_item.quantity_per_display_unit)::integer;
   INSERT INTO public.bottle_open_events(inventory_item_id,order_id,bottle_ml,automatic,opened_by)
   SELECT v_item.id,NULL,v_item.quantity_per_display_unit,true,auth.uid()
