  END IF;
  UPDATE public.inventory_items SET current_stock=current_stock-v_rec.qty,updated_at=now()
  WHERE id=v_item.id;
  INSERT INTO public.inventory_movements
   (inventory_item_id,movement_type,reason,quantity,direction,order_id,created_by,business)
