 INSERT INTO public.free_courtesies_v25
 (menu_item_id,item_name,business,quantity,unit_price,reason,authorized_by)
 VALUES(v_menu.id,v_menu.name,v_menu.business,p_quantity,v_menu.price,trim(p_reason),auth.uid())
 RETURNING id INTO v_id;
 RETURN jsonb_build_object('id',v_id,'item_name',v_menu.name,'quantity',p_quantity);
